Let~$C$ be a small category and consider the canonical concrete category
  structure on~$\hat C$ given by \Cref{ex:can-concrete-preasheaf-cat}. Given
  $P\in\hat C$ and $c\in C$, we write $\iota_c:P(c)\rightarrow\bigsqcup_{c\in C}P(c)$
  for the canonical injection. The category~$\operatorname{Elt}(\hat C)$ has
  \begin{itemize}
  \item as objects the pairs~$(P,\iota_c(x))$ where~$P \in \hat C$ and~$x \in
    P(c)$, and
  \item as morphisms from~$(P,\iota_c(x))$ to~$(Q,\iota_d(y))$ the natural
    transformations~$\alpha\colon P \Rightarrow Q$ such that~$c = d$ and~$\alpha_c(x) = y$.
  \end{itemize}
  \noindent Given~$(P,\iota_c(x)) \in \operatorname{Elt}(\hat C)$, we have the following.
  \begin{itemize}
  \item $(P,\iota_c(x))$ is principal when~$P$ is the smallest subpresheaf~$P'$
    of~$P$ such that~$x \in P'(c)$. In particular, for
    all~$c \in C$,~$(C(-,c),\iota_c(
  \def#2{c}
  \ifx#2\@empty
  \mathrm{id}^{}
  \else


  \mathrm{id}^{}_{c}
  \fi
))\in \operatorname{Elt}(\hat C)$ is principal.
  \item $(P,\iota_c(x))$ is primitive when the natural transformation~$\theta\colon
    C(-,c) \rightarrow P$ which maps~$
  \def#2{c}
  \ifx#2\@empty
  \mathrm{id}^{}
  \else


  \mathrm{id}^{}_{c}
  \fi
$ to~$x$ is an isomorphism.
  \end{itemize}

